 void load(){new Thread(new Runnable(){public void run(){try{String b=http(url+"/api/fields");if(b==null||b.trim().length()==0)b=http(url+"/api/telemetry");flat=flatJson(b);saveLap();}catch(Exception e){try{flat.put("__status","OFFLINE");}catch(Exception x){}}runOnUiThread(new Runnable(){public void run(){v.invalidate();}});}}).start();}
 String http(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(900);c.setReadTimeout(900);BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder sb=new StringBuilder();String l;while((l=br.readLine())!=null)sb.append(l);br.close();c.disconnect();return sb.toString();}
 JSONObject flatJson(String body)throws Exception{JSONObject out=new JSONObject();String s=body.trim();int a=s.indexOf('{'),b=s.lastIndexOf('}');Object root=new JSONTokener(a>=0&&b>a?s.substring(a,b+1):s).nextValue();flatInto(out,"",root);return out;}void flatInto(JSONObject out,String pre,Object obj)throws Exception{if(obj instanceof JSONObject){JSONObject o=(JSONObject)obj;Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();Object val=o.get(k);String p=pre.length()==0?k:pre+"."+k;flatInto(out,p,val);if(val instanceof JSONObject&&(k.equals("fields")||k.equals("telemetry")||k.equals("position")))flatInto(out,"",val);}}else out.put(pre,String.valueOf(obj));}
 String val(String...ks){try{for(String k:ks)if(flat.has(k)&&!flat.isNull(k)){String s=String.valueOf(flat.get(k));if(s.length()>0&&!s.equals("null")&&!s.equals("--"))return s;}}catch(Exception e){}return "--";}String lap(){return val("lastLaptime","lastLap","last_lap","last_lap_text","ultimaVolta");}String best(){return val("bestLaptime","bestLap","best_lap","best_lap_text","melhorVolta");}String lapNo(){return val("lapCount","lap","currentLap","completed_laps","voltasCorrigidas");}
 long parse(String r){try{if(r==null)return 0;String s=r.trim().replace(',','.');if(s.equals("--")||s.length()==0)return 0;if(!s.contains(":")){float n=Float.parseFloat(s);return n>1000?Math.round(n):Math.round(n*1000f);}String[] p=s.split(":");float sec=Float.parseFloat(p[p.length-1]);long m=p.length>=2?Long.parseLong(p[p.length-2]):0;long hr=p.length>=3?Long.parseLong(p[p.length-3]):0;return hr*3600000L+m*60000L+Math.round(sec*1000f);}catch(Exception e){return 0;}}
 String fmt(long ms){long hr=ms/3600000L;ms%=3600000L;long m=ms/60000L;ms%=60000L;long s=ms/1000L;long z=ms%1000L;return hr>0?String.format(Locale.US,"%02d:%02d:%02d.%03d",hr,m,s,z):String.format(Locale.US,"%02d:%02d.%03d",m,s,z);}long total(JSONArray a){long t=0;try{for(int i=0;i<a.length();i++)t+=parse(a.getJSONObject(i).optString("lap","--"));}catch(Exception e){}return t;}
 void saveLap(){String l=lap();if(l.equals("--")||l.equals(last))return;last=l;try{JSONArray a=new JSONArray(getSharedPreferences(PREF,0).getString(LAPS,"[]"));JSONObject o=new JSONObject();o.put("date",new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date()));o.put("track",track);o.put("car",car);o.put("lap",l);o.put("best",best());o.put("lapNo",lapNo());a.put(o);getSharedPreferences(PREF,0).edit().putString(LAPS,a.toString()).apply();}catch(Exception e){}}
 void edit(final String key,String title,String old){EditText in=new EditText(this);in.setText(old);new AlertDialog.Builder(this).setTitle(title).setView(in).setPositiveButton("Salvar",(d,w)->{String s=in.getText().toString().trim();if(s.length()>0){getSharedPreferences(PREF,0).edit().putString(key,s).apply();if(key.equals(TRACK))track=s;if(key.equals(CAR))car=s;v.invalidate();}}).setNegativeButton("Cancelar",null).show();}void editUrl(){EditText in=new EditText(this);in.setText(url);new AlertDialog.Builder(this).setTitle("Bridge URL").setView(in).setPositiveButton("Salvar",(d,w)->{url=in.getText().toString().trim();if(!url.startsWith("http"))url="http://"+url;getSharedPreferences(PREF,0).edit().putString(URL,url).apply();}).setNegativeButton("Cancelar",null).show();}void clear(){getSharedPreferences(PREF,0).edit().putString(LAPS,"[]").apply();v.invalidate();}
 class V extends View{Paint p=new Paint(1);RectF r=new RectF();float sc=1,scroll=0,lastY=0;int tab=0;ArrayList<F> fs=new ArrayList<>();V(Activity a){super(a);add("Speed","speed_kmh","speedKmh","velocityKmh","velocidade","kmh","speed");add("RPM","rpm","EngineRPM","engineRPM","engine_rpm","currentRpm");add("Gear","gear","currentGear","marcha","gears");add("Throttle","throttle","throttleFiltered","throttle_percent","acelerador");add("Brake","brake","brakeFiltered","brake_percent","freio");add("Fuel %","fuelPercent","fuel_percent","combustivelPorcentagem");add("Fuel Cap","fuelCapacity","fuel_capacity","tank_capacity");add("Lap","lapCount","lap","currentLap","completed_laps","voltasCorrigidas");add("Last Lap","lastLaptime","lastLap","last_lap","last_lap_text","ultimaVolta");add("Best Lap","bestLaptime","bestLap","best_lap","best_lap_text","melhorVolta");add("Pos X","position.x","positionX","posX","x");add("Pos Y","position.y","positionY","posY","y");}void add(String n,String...k){fs.add(new F(n,k));}
 protected void onDraw(Canvas c){sc=getWidth()/430f;c.save();c.scale(sc,sc);draw(c,430,getHeight()/sc);c.restore();}void draw(Canvas c,float w,float hh){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(0,5,10));c.drawRect(0,0,w,hh,p);txt(c,"GT7 BRIDGE MOBILE "+VERSION,14,28,16,Color.WHITE,1,Paint.Align.LEFT);txt(c,track+" · "+car,14,46,9,Color.rgb(80,190,255),0,Paint.Align.LEFT);txt(c,"BRIDGE",410,28,10,Color.rgb(255,80,100),1,Paint.Align.RIGHT);txt(c,"PISTA",348,48,9,Color.WHITE,1,Paint.Align.RIGHT);txt(c,"CARRO",410,48,9,Color.WHITE,1,Paint.Align.RIGHT);if(tab==0)scan(c,hh);else sess(c,hh);nav(c,w,hh);}void scan(Canvas c,float hh){c.save();c.translate(0,-scroll);float y=66;int ok=0,show=0;for(int i=0;i<fs.size();i++){if(hidden(i))continue;F f=fs.get(i);String vv=value(f);if(!vv.equals("--"))ok++;row(c,i,y,f.n,vv);y+=44;show++;}c.restore();foot(c,hh,"Scanner · visíveis "+show+" · funcionando "+ok);}void sess(Canvas c,float hh){JSONArray a=arr();c.save();c.translate(0,-scroll);float y=68;box(c,12,y,406,116);txt(c,"SESSÕES",24,y+25,14,Color.WHITE,1,Paint.Align.LEFT);txt(c,"APAGAR",400,y+25,9,Color.rgb(255,85,105),1,Paint.Align.RIGHT);txt(c,""+a.length(),78,y+62,21,Color.WHITE,1,Paint.Align.CENTER);txt(c,"VOLTAS",78,y+78,8,Color.GRAY,0,Paint.Align.CENTER);txt(c,"TEMPO TOTAL  "+fmt(total(a)),24,y+104,13,Color.rgb(0,230,130),1,Paint.Align.LEFT);y+=132;try{for(int i=a.length()-1;i>=0;i--){JSONObject o=a.getJSONObject(i);box(c,12,y,406,82);txt(c,o.optString("track"),24,y+22,12,Color.WHITE,1,Paint.Align.LEFT);txt(c,o.optString("lap"),400,y+22,13,Color.WHITE,1,Paint.Align.RIGHT);txt(c,o.optString("car"),24,y+44,11,Color.LTGRAY,1,Paint.Align.LEFT);txt(c,o.optString("date")+" · volta "+o.optString("lapNo"),24,y+64,9,Color.GRAY,0,Paint.Align.LEFT);y+=90;}}catch(Exception e){}c.restore();foot(c,hh,"Tempo total = soma das voltas gravadas");}
 JSONArray arr(){try{return new JSONArray(getSharedPreferences(PREF,0).getString(LAPS,"[]"));}catch(Exception e){return new JSONArray();}}void row(Canvas c,int i,float y,String n,String vv){box(c,10,y,410,38);txt(c,n,20,y+16,10,Color.rgb(180,215,235),0,Paint.Align.LEFT);txt(c,vv,20,y+32,12,vv.equals("--")?Color.GRAY:Color.WHITE,1,Paint.Align.LEFT);txt(c,"X",398,y+25,15,Color.rgb(255,75,95),1,Paint.Align.CENTER);}String value(F f){try{for(String k:f.k)if(flat.has(k)&&!flat.isNull(k)){String s=String.valueOf(flat.get(k));if(s.length()>0&&!s.equals("null"))return s;}}catch(Exception e){}return "--";}boolean hidden(int i){return getSharedPreferences(PREF,0).getBoolean("hide_"+i,false);}public boolean onTouchEvent(MotionEvent e){full();float x=e.getX()/sc,y=e.getY()/sc;if(e.getAction()==MotionEvent.ACTION_DOWN){lastY=y;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){scroll=Math.max(0,scroll-(y-lastY));lastY=y;invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(y<56&&x>350){editUrl();return true;}if(y<56&&x>270&&x<350){edit(TRACK,"Nome da pista",track);return true;}if(y<56&&x>205&&x<270){edit(CAR,"Nome do carro",car);return true;}if(y>getHeight()/sc-58){tab=x<215?0:1;scroll=0;invalidate();return true;}if(tab==0&&x>365){int row=(int)((y+scroll-66)/44);if(row>=0&&row<fs.size())getSharedPreferences(PREF,0).edit().putBoolean("hide_"+row,true).apply();invalidate();return true;}if(tab==1&&x>320&&y+scroll<120){clear();return true;}}return true;}void foot(Canvas c,float hh,String s){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(0,5,10));c.drawRect(0,hh-82,430,hh,p);txt(c,s,14,hh-64,9,Color.WHITE,0,Paint.Align.LEFT);}void nav(Canvas c,float w,float hh){float y=hh-50;box(c,8,y,414,42);txt(c,"SCANNER",108,y+27,11,tab==0?Color.rgb(0,230,130):Color.WHITE,1,Paint.Align.CENTER);txt(c,"SESSÕES",322,y+27,11,tab==1?Color.rgb(0,230,130):Color.WHITE,1,Paint.Align.CENTER);}void box(Canvas c,float x,float y,float w,float h){r.set(x,y,x+w,y+h);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(14,16,18));c.drawRoundRect(r,8,8,p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.rgb(45,45,45));p.setStrokeWidth(1);c.drawRoundRect(r,8,8,p);}void txt(Canvas c,String s,float x,float y,float z,int col,int bold,Paint.Align a){p.setStyle(Paint.Style.FILL);p.setColor(col);p.setTextSize(z);p.setTextAlign(a);p.setTypeface(bold==1?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);c.drawText(s==null?"--":s,x,y,p);}}
